int bubbleSort(int x[],int y)
{
    int i,j,temp;
    for(i=0;i<y;i++)
    {
        for(j=0;j<y-i-1;j++)
        {
            if(x[j] > x[j+1])
            {
                temp = x[j];
                x[j] = x[j+1];
                x[j+1] = temp;
            }
        }
    }
    printf("sorted array:\n");
